selector_to_html = {"a[href=\"multi-platform-training.html#switch-to-the-flagos-compiler-and-operator-library\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Switch to the FlagOS compiler and operator library<a class=\"headerlink\" href=\"#switch-to-the-flagos-compiler-and-operator-library\" title=\"Link to this heading\">#</a></h2><p>The training job above uses the vendor operator library. To run on the FlagOS stack instead, replace Triton with FlagTree and install FlagGems.</p>", "a[href=\"override-usage.html#replacing-a-class-method\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Replacing a Class Method<a class=\"headerlink\" href=\"#replacing-a-class-method\" title=\"Link to this heading\">#</a></h2><p><strong>Scenario</strong>: Replace a single method in a class while keeping other methods unchanged.</p>", "a[href=\"multi-platform-training.html#known-issues-and-workarounds\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. Known issues and workarounds<a class=\"headerlink\" href=\"#known-issues-and-workarounds\" title=\"Link to this heading\">#</a></h2><h3>7.1 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014 PyTorch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> imports <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code> from Triton, which FlagTree does not provide. Add a compatibility shim to <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code>:</p>", "a[href=\"multi-platform-training.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-Platform Training and Testing<a class=\"headerlink\" href=\"#multi-platform-training-and-testing\" title=\"Link to this heading\">#</a></h1><p>This guide walks through installing Megatron-LM-FL and running an end-to-end Qwen3 training job on four non-NVIDIA platforms: MetaX, Hygon, Ascend, and T-Head PPU. Every command, configuration file, and log excerpt below was collected from a real validation run on each platform.</p><p>The workflow uses three FlagOS components together:</p>", "a[href=\"override-usage.html#replacing-a-module-level-function\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Replacing a Module-Level Function<a class=\"headerlink\" href=\"#replacing-a-module-level-function\" title=\"Link to this heading\">#</a></h2><p><strong>Scenario</strong>: Replace a standalone function in a module.</p>", "a[href=\"override-usage.html#multi-vendor-support\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-Vendor Support<a class=\"headerlink\" href=\"#multi-vendor-support\" title=\"Link to this heading\">#</a></h2><p>Multiple vendor implementations can be registered for the same target, selected via environment variable:</p>", "a[href=\"multi-platform-training.html#prepare-the-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Prepare the environment<a class=\"headerlink\" href=\"#prepare-the-environment\" title=\"Link to this heading\">#</a></h2><h3>2.1 Clone the repositories<a class=\"headerlink\" href=\"#clone-the-repositories\" title=\"Link to this heading\">#</a></h3>", "a[href=\"override-usage.html#quick-start-checklist\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Start Checklist<a class=\"headerlink\" href=\"#quick-start-checklist\" title=\"Link to this heading\">#</a></h2>", "a[href=\"override-usage.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Override Plugin Mechanism<a class=\"headerlink\" href=\"#override-plugin-mechanism\" title=\"Link to this heading\">#</a></h1><p>This document describes how to use the <code class=\"docutils literal notranslate\"><span class=\"pre\">@overridable</span></code> / <code class=\"docutils literal notranslate\"><span class=\"pre\">register()</span></code> plugin system in FlagScale, which supports replacing <code class=\"docutils literal notranslate\"><span class=\"pre\">megatron.core</span></code> (Megatron-LM-FL side) and <code class=\"docutils literal notranslate\"><span class=\"pre\">megatron.training</span></code> (FlagScale side) implementations.</p><p>Three replacement scenarios are supported:</p>", "a[href=\"multi-platform-training.html#supported-platforms\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Supported platforms<a class=\"headerlink\" href=\"#supported-platforms\" title=\"Link to this heading\">#</a></h2>", "a[href=\"multi-platform-training.html#prepare-the-dataset-and-tokenizer\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Prepare the dataset and tokenizer<a class=\"headerlink\" href=\"#prepare-the-dataset-and-tokenizer\" title=\"Link to this heading\">#</a></h2>", "a[href=\"multi-platform-training.html#run-the-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Run the training test<a class=\"headerlink\" href=\"#run-the-training-test\" title=\"Link to this heading\">#</a></h2><h3>5.1 Model configuration<a class=\"headerlink\" href=\"#model-configuration\" title=\"Link to this heading\">#</a></h3><p>Edit <code class=\"docutils literal notranslate\"><span class=\"pre\">./examples/qwen3/conf/train/0_6b.yaml</span></code> to point at the local dataset and tokenizer, and shrink the batch sizes so the job fits a single node:</p>", "a[href=\"override-usage.html#core-concepts\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Core Concepts<a class=\"headerlink\" href=\"#core-concepts\" title=\"Link to this heading\">#</a></h2>", "a[href=\"multi-platform-training.html#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#megatron-lm-fl-user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Megatron-LM-FL User Guide<a class=\"headerlink\" href=\"#megatron-lm-fl-user-guide\" title=\"Link to this heading\">#</a></h1><p>This section provides detailed guidance on using Megatron-LM-FL. For end-to-end training workflows\uff0csee <a class=\"reference external\" href=\"https://docs.flagos.io/projects/TransformerEngine-FL/en/latest/user_guide/e2e-use-case.html\">End-to-End Use Case: TransformerEngine-FL + Megatron-LM-FL + FlagScale</a>.</p>", "a[href=\"override-usage.html#replacing-an-entire-class\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Replacing an Entire Class<a class=\"headerlink\" href=\"#replacing-an-entire-class\" title=\"Link to this heading\">#</a></h2><p><strong>Scenario</strong>: Completely replace an original class with a new class. All places that instantiate the original class automatically receive the replacement class.</p>", "a[href=\"multi-platform-training.html#install-megatron-lm-fl\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Install Megatron-LM-FL<a class=\"headerlink\" href=\"#install-megatron-lm-fl\" title=\"Link to this heading\">#</a></h2><p>Verify the installed version:</p>", "a[href=\"override-usage.html#method-key-generation-rules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">method_key Generation Rules<a class=\"headerlink\" href=\"#method-key-generation-rules\" title=\"Link to this heading\">#</a></h2><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">target</span></code> parameter of <code class=\"docutils literal notranslate\"><span class=\"pre\">register()</span></code> is automatically converted to an internal method_key:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
